<script setup>import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import {Head,Link,router} from '@inertiajs/vue3'; const props=defineProps({assets:Object,filters:Object}); const toggle=()=>router.get(route('exposure.index'),{exposed:props.filters.exposed?0:1},{preserveState:true});</script>
<template><Head title="Exposure"/><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><h1 class="text-xl font-semibold">Exposure monitor</h1><p class="mt-1 text-sm text-slate-500">Devices currently reachable from the internet and their latest check.</p></div><button @click="toggle" class="rounded-lg border border-slate-300 px-4 py-2 text-sm font-medium">{{filters.exposed?'Show all assets':'Show exposed only'}}</button></div></template><div class="mx-auto max-w-7xl px-4 py-8"><div class="overflow-hidden rounded-xl border bg-white shadow-sm"><table class="min-w-full divide-y divide-slate-200"><thead class="bg-slate-50 text-left text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Device</th><th class="px-5 py-3">Site</th><th class="px-5 py-3">Current state</th><th class="px-5 py-3">Last checked</th><th class="px-5 py-3">Method</th></tr></thead><tbody class="divide-y divide-slate-100 text-sm"><tr v-for="asset in assets.data" :key="asset.id"><td class="px-5 py-4"><Link :href="route('assets.show',asset.id)" class="font-semibold text-teal-800">{{asset.name}}</Link><div class="text-slate-500">{{asset.external_ip||'No public IP recorded'}}</div></td><td class="px-5 py-4">{{asset.site.name}}</td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="asset.is_internet_facing?'bg-red-100 text-red-800':'bg-emerald-100 text-emerald-800'">{{asset.is_internet_facing?'Reachable from internet':'Not known to be exposed'}}</span></td><td class="px-5 py-4 text-slate-600">{{asset.exposure_scans[0]?new Date(asset.exposure_scans[0].scanned_at).toLocaleString():'Never checked'}}</td><td class="px-5 py-4 capitalize text-slate-600">{{asset.exposure_scans[0]?.method||'—'}}</td></tr><tr v-if="!assets.data.length"><td colspan="5" class="px-5 py-12 text-center text-slate-500">No assets to display.</td></tr></tbody></table></div></div></AuthenticatedLayout></template>
